//! 🧪️ Completed canonical receiving proves exact handle/mesh transfer and physical custody against Serde.
use super::*;
use semio_framework_os_flow_host_session::preview_receiving::*;
use semio_framework_value::{RetirementDemand, ValueRefusalKind};
use semio_framework_value::retained_clone::RetainedCloneGrant;
use semio_framework_value::retirement::controlled::ControlledRetirement;
use semio_framework_value::{DslValue, Number};
use semio_framework_job::{OperationId,Generation};
use semio_framework_value::ToValue;
fn observe<T>(action:impl FnOnce()->T)->(T,(usize,usize)){let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(action);(result,(heap.requested_bytes,heap.released_bytes))}
fn dto(value:&serde_json::Value)->DslValue{match value{serde_json::Value::Null=>DslValue::Null,serde_json::Value::Bool(value)=>DslValue::Bool(*value),serde_json::Value::Number(value)=>DslValue::Number(value.as_u64().map(Number::UInt).unwrap_or_else(||Number::Float(value.as_f64().unwrap()))),serde_json::Value::String(value)=>DslValue::String(value.clone()),serde_json::Value::Array(value)=>DslValue::Array(value.iter().map(dto).collect()),serde_json::Value::Object(value)=>DslValue::Object(value.iter().map(|(key,value)|(key.clone(),dto(value))).collect())}}
fn fixture()->serde_json::Value{serde_json::from_str(read_node("📥️evaluation-source/🔎️read/📨️response/🧪️tests/🧫️fixtures/🔣️.json")).unwrap()}
fn preview_finite_caller()->semio_framework_job::OriginalJobFixtureCaller{let law:serde_json::Value=serde_json::from_str(read_node("📥️preview/🧪️tests/🧫️fixtures/🔁️replacement.json")).unwrap();let source=&law["caller"];assert_eq!(occupied_policy(&source["turn"]),PREVIEW_FIXED_TURN);semio_framework_job::OriginalJobFixtureCaller::admit(OperationId(source["operation"].as_u64().unwrap()),Generation(source["generation"].as_u64().unwrap()),occupied_policy(&source["stock"]),||Some(1000),source["deadline"].as_u64().unwrap(),source["fuel"].as_u64().unwrap())}
const PREVIEW_FIXED_TURN:RetainedCloneGrant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:1048576,maximum_release_bytes:268435456,maximum_depth:4096};
fn preview_finite_grant(body:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:body,..PREVIEW_FIXED_TURN}}
fn preview_finite_close(receiver:&mut FlowPreviewCompletedReceiver,session:&mut FlowEvalSession,issuer:&mut semio_framework_job::OriginalJobFixtureCaller,body:usize)->(usize,usize){let mut total=(0,0);receiver.begin_close();for turn in 0..65536{if receiver.terminal_is_empty(){break}let(step,heap)=observe(||issuer.turn(preview_finite_grant(body),|cx|receiver.close_step(cx)));step.unwrap();let progress=issuer.receipt();assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));total.0+=heap.0;total.1+=heap.1;assert!(turn<65535)}assert!(receiver.terminal_is_empty());session.begin_close();for turn in 0..65536{if session.terminal_is_empty(){return total}let(step,heap)=observe(||issuer.turn(preview_finite_grant(body),|cx|{let demand=RetirementDemand{copy_bytes:session.next_close_copy_byte_demand()?,capacity_bytes:session.next_close_capacity_byte_demand(body)?,release_bytes:session.next_close_release_byte_demand()?,depth:session.next_close_depth_demand()?};semio_framework_job::close_original_retained_step(cx,demand,|grant|session.close_step(grant))}));step.unwrap();let progress=issuer.receipt();assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));total.0+=heap.0;total.1+=heap.1;assert!(turn<65535)}unreachable!()}

#[test]
fn original_completed_preview_moves_mesh16_into_paid_cache_with_full_custody(){
 let mut fixture=fixture();fixture["nodeHash"]=serde_json::json!(u64::MAX);let oracle=dto(&fixture["mesh"]);
 for body in [1,3,64]{let mut issuer=preview_finite_caller();let((value,mut session),heap)=observe(||(dto(&fixture),FlowEvalSession::new()));let mut sums=heap;let handle_pointer=object(&value).unwrap().iter().find(|(key,_)|key=="handle").map(|(_,value)|text(value).unwrap().as_ptr()).unwrap();let(mut receiver,heap)=observe(||issuer.turn(preview_finite_grant(body),|cx|Ok(FlowPreviewCompletedReceiver::new(value,cx).unwrap_or_else(|_|panic!("original receiver intake")))).unwrap());assert_eq!(heap,(0,0));let address=FlowPreviewCompletedAddress{window_id:fixture["windowId"].as_str().unwrap(),window_kind_id:fixture["windowKindId"].as_str().unwrap(),handle:fixture["handle"].as_str().unwrap(),node_hash:u64::MAX,tolerance:fixture["tolerance"].as_f64().unwrap()};let mut positions_pointer=None;
  for turn in 0..65536{if receiver.terminal_is_empty(){break}let d=session.next_preview_tessellate_demands(&receiver,body).unwrap();let g=preview_finite_grant(body);let before=(receiver.scan,receiver.field,receiver.phase,receiver.offset,receiver.slots,session.preview_mesh_by_handle.len());for denied in [Some(RetainedCloneGrant{maximum_items:0,..g}),Some(RetainedCloneGrant{maximum_depth:0,..g}),(d.capacity_bytes>0).then(||RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g}),(d.release_bytes>0).then(||RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g}),(d.copy_bytes>0&&session.next_preview_tessellate_demands(&receiver,d.copy_bytes-1).unwrap().copy_bytes>d.copy_bytes-1).then(||RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g})].into_iter().flatten(){let fuel=issuer.fuel_remaining();let ledger=issuer.cumulative_receipt();let(result,heap)=observe(||issuer.turn(denied,|cx|session.resolve_preview_tessellate(&mut receiver,&address,cx)));assert!(!result.unwrap());assert_eq!(heap,(0,0));assert_eq!(issuer.cumulative_receipt(),ledger);assert_eq!(issuer.fuel_remaining(),fuel);assert_eq!((receiver.scan,receiver.field,receiver.phase,receiver.offset,receiver.slots,session.preview_mesh_by_handle.len()),before)}for(fuel,deadline)in[(0,1500),(1,1000)]{let original=issuer.fuel_remaining();let ledger=issuer.cumulative_receipt();let(result,heap)=observe(||issuer.turn(g,|cx|cx.with_original_work_loan(fuel,deadline,|same|session.resolve_preview_tessellate(&mut receiver,&address,same))));assert!(!result.unwrap());assert_eq!(heap,(0,0));assert_eq!(issuer.cumulative_receipt(),ledger);assert_eq!(issuer.fuel_remaining(),original)}let(result,heap)=observe(||issuer.turn(g,|cx|session.resolve_preview_tessellate(&mut receiver,&address,cx)));let progress=issuer.receipt();assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));sums.0+=heap.0;sums.1+=heap.1;result.unwrap();if let Some(mesh)=receiver.fields.as_ref().and_then(|fields|fields.mesh.as_ref()){positions_pointer=Some(mesh.positions.as_ptr())}if d.copy_bytes>body{assert_eq!(progress,Default::default());break}assert!(turn<65535)}
  if body==64{assert!(receiver.terminal_is_empty()&&receiver.committed);let(handle,mesh)=session.preview_mesh_by_handle.iter().next().unwrap();assert_eq!(handle.as_ptr(),handle_pointer);assert_eq!(Some(mesh.positions.as_ptr()),positions_pointer);assert_eq!(mesh.to_value(),oracle)}else{assert!(session.preview_mesh_by_handle.is_empty())}issuer.cancel().cancel_now();let returned=preview_finite_close(&mut receiver,&mut session,&mut issuer,body);sums.0+=returned.0;sums.1+=returned.1;assert_eq!(sums.0,sums.1);assert_eq!(observe(||drop(receiver)).1,(0,0));assert_eq!(observe(||drop(session)).1,(0,0));let stock=issuer.stock();issuer.retire(stock);
 }
}
#[test]
fn original_completed_preview_refuses_late_cancel_and_business_mismatch_before_cache_commit(){
 for mismatch in [false,true]{let fixture=fixture();let mut issuer=preview_finite_caller();let((value,mut session),heap)=observe(||(dto(&fixture),FlowEvalSession::new()));let mut sums=heap;let mut receiver=issuer.turn(preview_finite_grant(64),|cx|Ok(FlowPreviewCompletedReceiver::new(value,cx).unwrap_or_else(|_|panic!("original receiver intake")))).unwrap();let address=FlowPreviewCompletedAddress{window_id:fixture["windowId"].as_str().unwrap(),window_kind_id:fixture["windowKindId"].as_str().unwrap(),handle:fixture["handle"].as_str().unwrap(),node_hash:if mismatch{0}else{fixture["nodeHash"].as_u64().unwrap()},tolerance:fixture["tolerance"].as_f64().unwrap()};let mut failure=None;
  for turn in 0..65536{if !mismatch&&receiver.phase==9{issuer.cancel().cancel_now()}let fuel=issuer.fuel_remaining();let(result,heap)=observe(||issuer.turn(preview_finite_grant(64),|cx|session.resolve_preview_tessellate(&mut receiver,&address,cx)));let progress=issuer.receipt();assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));sums.0+=heap.0;sums.1+=heap.1;if let Err(original)=result{assert_eq!(original.primary_value().unwrap().kind,ValueRefusalKind::InvalidValue);assert!(original.receipt_refusal.is_none());assert_eq!(issuer.fuel_remaining(),fuel-1);failure=Some(original);break}if issuer.cancel().is_cancelled_now(){assert_eq!(heap,(0,0));assert_eq!(progress,Default::default());break}assert!(turn<65535)}assert_eq!(failure.is_some(),mismatch);assert!(session.preview_mesh_by_handle.is_empty());issuer.cancel().cancel_now();let mut closing=ControlledRetirement::new(failure).unwrap_or_else(|_|panic!("original native refusal close"));for turn in 0..65536{if closing.terminal_is_empty(){break}let(result,heap)=observe(||issuer.turn(preview_finite_grant(3),|cx|semio_framework_job::close_original_retained_step(cx,closing.selected_demand(3)?,|grant|closing.step(grant))));result.unwrap();let progress=issuer.receipt();assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));sums.0+=heap.0;sums.1+=heap.1;assert!(turn<65535)}assert!(closing.terminal_is_empty());assert_eq!(observe(||drop(closing)).1,(0,0));let returned=preview_finite_close(&mut receiver,&mut session,&mut issuer,3);sums.0+=returned.0;sums.1+=returned.1;assert_eq!(sums.0,sums.1);assert_eq!(observe(||drop(receiver)).1,(0,0));assert_eq!(observe(||drop(session)).1,(0,0));let stock=issuer.stock();issuer.retire(stock);
 }
}

fn occupied_policy(value:&serde_json::Value)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:value["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:value["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:value["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:value["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:value["maximumDepth"].as_u64().unwrap()as usize}}
#[test]
fn original_completed_preview_replaces_same_handle_without_copying_or_losing_original_mesh(){
 use semio_framework_job::OriginalJobFixtureCaller;
 let law:serde_json::Value=serde_json::from_str(read_node("📥️preview/🧪️tests/🧫️fixtures/🔁️replacement.json")).unwrap();let source=&law["caller"];let stock=occupied_policy(&source["stock"]);let grant=occupied_policy(&source["turn"]);let mut issuer=OriginalJobFixtureCaller::admit(OperationId(source["operation"].as_u64().unwrap()),Generation(source["generation"].as_u64().unwrap()),stock,||Some(1000),source["deadline"].as_u64().unwrap(),source["fuel"].as_u64().unwrap());let fixture=fixture();let(mut session,heap)=observe(FlowEvalSession::new);let mut sums=heap;
 let address=FlowPreviewCompletedAddress{window_id:fixture["windowId"].as_str().unwrap(),window_kind_id:fixture["windowKindId"].as_str().unwrap(),handle:fixture["handle"].as_str().unwrap(),node_hash:fixture["nodeHash"].as_u64().unwrap(),tolerance:fixture["tolerance"].as_f64().unwrap()};let mut previous=None;
 for round in 0..law["rounds"].as_u64().unwrap(){let prior_epoch=session.preview_mesh_epoch();let(value,heap)=observe(||dto(&fixture));sums.0+=heap.0;sums.1+=heap.1;let handle_pointer=object(&value).unwrap().iter().find(|(key,_)|key=="handle").map(|(_,value)|text(value).unwrap().as_ptr()).unwrap();let(mut receiver,heap)=observe(||issuer.turn(grant,|cx|Ok(FlowPreviewCompletedReceiver::new(value,cx).unwrap_or_else(|_|panic!("original occupied intake")))).unwrap());assert_eq!(heap,(0,0));let mut incoming=None;let mut displaced=false;
  for turn in 0..65536{if receiver.terminal_is_empty(){break}let before=issuer.fuel_remaining();for(fuel,deadline)in[(0,1500),(1,1000)]{let ledger=issuer.cumulative_receipt();let(result,heap)=observe(||issuer.turn(grant,|cx|cx.with_original_work_loan(fuel,deadline,|same|session.resolve_preview_tessellate(&mut receiver,&address,same))));assert!(!result.unwrap());assert_eq!(heap,(0,0));assert_eq!(issuer.cumulative_receipt(),ledger);assert_eq!(issuer.fuel_remaining(),before)}let(result,heap)=observe(||issuer.turn(grant,|cx|session.resolve_preview_tessellate(&mut receiver,&address,cx)));let progress=issuer.receipt();assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));sums.0+=heap.0;sums.1+=heap.1;result.unwrap();if let Some(mesh)=receiver.fields.as_ref().and_then(|fields|fields.mesh.as_ref()){incoming=Some(mesh.positions.as_ptr())}if let Some((handle,mesh))=receiver.fields.as_ref().and_then(|fields|fields.displaced.as_ref()).and_then(ControlledRetirement::original){assert_eq!(Some((handle.as_ptr(),mesh.positions.as_ptr())),previous);displaced=true}assert!(turn<65535)}
  assert!(receiver.terminal_is_empty()&&receiver.received&&receiver.committed);assert_eq!(session.preview_mesh_by_handle.len(),law["expectedEntries"].as_u64().unwrap()as usize);let(handle,mesh)=session.preview_mesh_by_handle.iter().next().unwrap();assert_eq!(handle.as_ptr(),handle_pointer);assert_eq!(Some(mesh.positions.as_ptr()),incoming);if round==1{assert!(displaced);assert_ne!(Some((handle.as_ptr(),mesh.positions.as_ptr())),previous)}previous=Some((handle.as_ptr(),mesh.positions.as_ptr()));assert_eq!(mesh.to_value(),dto(&fixture["mesh"]));let epoch=session.preview_mesh_epoch();assert!(epoch>prior_epoch);let slot=(0..session.preview_mesh_slot_count()).find(|slot|session.preview_mesh_at_slot(*slot,epoch).unwrap().is_some()).unwrap();let((same_handle,same_mesh),heap)=observe(||session.preview_mesh_at_slot(slot,epoch).unwrap().unwrap());assert_eq!(heap,(0,0));assert_eq!(same_handle.as_ptr(),handle_pointer);assert_eq!(Some(same_mesh.positions.as_ptr()),incoming);let(refusal,heap)=observe(||session.preview_mesh_at_slot(slot,prior_epoch));assert!(refusal.is_err());assert_eq!(heap,(0,0));assert_eq!(observe(||drop(receiver)).1,(0,0));
 }
 issuer.cancel().cancel_now();session.begin_close();for turn in 0..65536{if session.terminal_is_empty(){break}let(result,heap)=observe(||issuer.turn(RetainedCloneGrant{maximum_copy_bytes:3,..grant},|cx|{let demand=RetirementDemand{copy_bytes:session.next_close_copy_byte_demand()?,capacity_bytes:session.next_close_capacity_byte_demand(3)?,release_bytes:session.next_close_release_byte_demand()?,depth:session.next_close_depth_demand()?};semio_framework_job::close_original_retained_step(cx,demand,|grant|session.close_step(grant))}));result.unwrap();let progress=issuer.receipt();assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));sums.0+=heap.0;sums.1+=heap.1;assert!(turn<65535)}assert!(session.terminal_is_empty());assert_eq!(observe(||drop(session)).1,(0,0));assert_eq!(sums.0,sums.1);issuer.retire(stock);
}

/// 📈️ Original owner phases remain cancellable and preserve the actual bilingual progress vocabulary.
#[test]
fn original_completed_preview_progress_phases_preserve_actual_geometry_admission(){
 let schema:serde_json::Value=serde_json::from_str(read_node("../🧩️extensions/🕸️wasm/🧬️schema/📐️tessellation/📈️progress/🔣️.json")).unwrap();
 for tag in schema["properties"]["phase"]["enum"].as_array().unwrap(){let tag=tag.as_str().unwrap();let phase=PreviewTessellatePhase::from_tag(tag);assert_eq!(phase.tag(),tag);assert!(phase.is_cancellable());let(en,de)=phase.labels();assert!(!en.is_empty()&&!de.is_empty());assert_ne!(en,de);}
}
